const desk24=renderDesktop;renderDesktop=function(){desk24();const host=screen.querySelector('.desktop-page');if(!host)return;const c=document.createElement('section');c.className='water-widget24';c.innerHTML='<button id="waterOpen24" aria-label="查看喝水统计"><span class="glass24"><svg viewBox="0 0 40 44" aria-hidden="true"><path d="m8 8 3 29h18l3-29z" fill="none" stroke="currentColor" stroke-width="2"/><path d="M11 24q9-6 18 0l-1 11H12z" fill="currentColor" opacity=".2"/><path d="M14 15h12M17 29h1m5 0h1" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></span><span><b>喝水打卡</b><small id="cups24"></small></span></button><button id="addWater24">＋ 一杯</button><button id="undoWater24" aria-label="撤销今天最后一杯">↶</button>';host.querySelector('.desktop-apps').before(c);$('#waterOpen24').onclick=()=>go('water24');$('#addWater24').onclick=()=>drink24();$('#undoWater24').onclick=()=>drink24(true);updateWater24()};
function waterPage24(){const s=F24.stats(water24,day24(),waterRange24),today=water24.filter(x=>x.date===day24()).length;const groups={};if(waterRange24===365){for(const[k,v]of Object.entries(s.counts))groups[k.slice(0,7)]=(groups[k.slice(0,7)]||0)+v}else{for(let d=s.start;d<=day24();d=F24.add(d,1))groups[d]=s.counts[d]||0}const max=Math.max(1,...Object.values(groups));shell24('喝水打卡','小口喝水，慢慢照顾自己',`<div class="hero24 water-hero24"><span>今天已记录</span><strong>${today}<small> 杯</small></strong><div class="actions"><button class="primary" id="drink24">＋ 加一杯</button><button class="secondary" id="undoDrink24" ${today?'':'disabled'}>↶ 撤销最后一杯</button></div></div><div class="tabs24">${[[7,'最近一周'],[30,'最近一月'],[365,'最近一年']].map(([n,t])=>`<button data-water-range="${n}" aria-pressed="${waterRange24===n}">${t}</button>`).join('')}</div><div class="card24"><h3>共 ${s.total} 杯</h3><p>${s.start} — ${day24()}</p>${Object.entries(groups).map(([k,v])=>`<div class="water-row24"><small>${k.slice(5)||k}</small><i style="--fill:${v/max*100}%"></i><b>${v} 杯</b></div>`).join('')}</div>`);$('#drink24').onclick=()=>drink24();$('#undoDrink24').onclick=()=>drink24(true);screen.querySelectorAll('[data-water-range]').forEach(b=>b.onclick=()=>{waterRange24=Number(b.dataset.waterRange);waterPage24()})}
