function calendar24(renderDay){const start=F24.date(month24+'-01'),offset=(start.getDay()+6)%7,days=new Date(start.getFullYear(),start.getMonth()+1,0).getDate();return `<div class="month24"><button id="monthPrev24" aria-label="上个月">‹</button><b>${month24.replace('-',' 年 ')} 月</b><button id="monthNext24" aria-label="下个月">›</button></div><div class="grid24">${['一','二','三','四','五','六','日'].map(x=>`<small>${x}</small>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=month24+'-'+String(i+1).padStart(2,'0');return renderDay(d,i+1)}).join('')}</div>`}
