const oldDiary24=wxDiary;wxDiary=function(date){if(typeof date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(date))month24=date.slice(0,7);shell24('心情日记','同一天，收藏你和 TA 各自的小情绪',`<div class="card24"><div class="people24">${['me',...roles.map(r=>r.id)].map(id=>`<label class="check"><input type="checkbox" data-person24="${escapeHtml(id)}" ${people24.includes(id)?'checked':''}>${escapeHtml(id==='me'?profile.name:roles.find(r=>r.id===id)?.name)}</label>`).join('')}</div>${calendar24((d,n)=>`<button class="mood-day24 ${d===day24()?'today24':''}" data-mood-date="${d}"><b>${n}</b><span>${people24.slice(0,4).map(id=>moods24[d]?.[id]?`<span title="${escapeHtml(id==='me'?profile.name:roles.find(r=>r.id===id)?.name||'角色')}">${face24(moods24[d][id].mood)}<small>${escapeHtml(id==='me'?'我':roles.find(r=>r.id===id)?.name.slice(0,2)||'TA')}</small></span>`:'').join('')}</span></button>`)}</div><button class="primary full" id="moodToday24">记录今天的心情</button><button class="secondary full" id="aiDiary24">请聊天对象写一篇日记</button><h3>文字日记 · 已有 ${wx18.diaries.length} 篇</h3>${wx18.diaries.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<button class="entry24" data-entry24="${escapeHtml(e.id)}"><small>${e.date}</small><b>${escapeHtml(e.title)}</b><p>${escapeHtml(e.text.slice(0,100))}</p></button>`).join('')}<button class="secondary full" id="newText24">写文字日记</button>`);monthBind24(wxDiary);screen.querySelectorAll('[data-person24]').forEach(i=>i.onchange=()=>{people24=[...screen.querySelectorAll('[data-person24]:checked')].map(x=>x.dataset.person24);wxDiary()});screen.querySelectorAll('[data-mood-date]').forEach(b=>b.onclick=()=>editMood24(b.dataset.moodDate));$('#moodToday24').onclick=()=>editMood24(day24());$('#aiDiary24').onclick=diaryGenerate22;$('#newText24').onclick=()=>wxEntryEditor('diaries',null,day24());screen.querySelectorAll('[data-entry24]').forEach(b=>b.onclick=()=>wxEntryEditor('diaries',b.dataset.entry24))};
function editMood24(date){if(date>day24()){toast('先记录已经经历的今天吧');return}let who=people24[0]||'me',chosen='calm';const d=wxPanel(`<h2>${date} · 心情小记</h2><label>是谁的心情？<select id="moodWho24">${['me',...roles.map(r=>r.id)].map(id=>`<option value="${escapeHtml(id)}">${escapeHtml(id==='me'?profile.name:roles.find(r=>r.id===id)?.name)}</option>`).join('')}</select></label><div class="faces24">${feelings24.map(([id,name])=>`<button data-face24="${id}" aria-label="${name}">${face24(id)}<small>${name}</small></button>`).join('')}</div><label>想留下的话<textarea id="moodNote24" rows="3" maxlength="2000"></textarea></label><button id="saveMood24" class="primary full">保存心情</button><button id="removeMood24" class="secondary full">清除这一条心情</button>`);const load=()=>{const m=moods24[date]?.[who];chosen=m?.mood||'calm';$('#moodNote24').value=m?.note||'';d.querySelectorAll('[data-face24]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.face24===chosen))};$('#moodWho24').value=who;$('#moodWho24').onchange=e=>{who=e.target.value;load()};d.querySelectorAll('[data-face24]').forEach(b=>b.onclick=()=>{chosen=b.dataset.face24;d.querySelectorAll('[data-face24]').forEach(x=>x.setAttribute('aria-pressed',x===b))});const save=remove=>{try{const entries={...moods24[date]};if(remove)delete entries[who];else entries[who]={mood:chosen,note:$('#moodNote24').value};const next={...moods24,[date]:entries};localSave('moods24',next);moods24=next;d.close();wxDiary()}catch(e){toast(e.message)}};$('#saveMood24').onclick=()=>save(false);$('#removeMood24').onclick=()=>save(true);load()}
const calendarPrior24=renderCalendar;renderCalendar=function(){calendarPrior24();screen.querySelectorAll('[data-date]').forEach(b=>{const records=moods24[b.dataset.date];if(!records)return;const s=document.createElement('span');s.className='calendar-faces24';s.innerHTML=Object.values(records).slice(0,2).map(m=>face24(m.mood)).join('');b.append(s)})};
