let period24=localRead('period24',{length:5,active:null,days:{}}),periodMonth24=day24().slice(0,7);
function periodSave24(n){localSave('period24',n);period24=n}
renderPeriod=function(){const info=F24.cycle(periods,periodCycle,period24.length),today=day24(),active=period24.active,remaining=info.next?Math.round((F24.date(info.next)-F24.date(today))/86400000):null,offset=active?Math.round((F24.date(today)-F24.date(active))/86400000)+1:null,previousMonth=month24;month24=periodMonth24;const calendar=calendar24((d,n)=>{const actual=periods.some(p=>d>=p.start&&d<=p.end)||(active&&d>=active&&d<=today),pred=info.next&&d>=info.next&&d<F24.add(info.next,period24.length);return `<button data-period24="${d}" class="${actual?'actual24':pred?'pred24':''} ${d===today?'today24':''}">${n}${period24.days[d]?'<i>·</i>':''}</button>`});month24=previousMonth;shell24('生理期','记录身体的小节奏，也给自己一点温柔',`<div class="hero24 period-ring24"><div><small>${active?'经期第':remaining===null?'从第一次记录开始':remaining<0?'比预计日期晚':'距离下次预计经期'}</small><strong>${offset|| (remaining===null?'✿':Math.abs(remaining))}</strong><small>${remaining===null&&!active?'添加一条记录':'天'}</small></div></div><div class="stat24"><span><b>${info.average}</b>参考周期</span><span><b>${period24.length}</b>经期天数</span><span><b>${info.next?.slice(5)||'—'}</b>下次预计</span></div><div class="actions"><button class="primary" id="periodStart24">${active?'今天结束了':'今天开始了'}</button><button class="secondary" id="periodOther24">补记 / 编辑</button><button class="secondary" id="periodSettings24">周期设置</button></div><div class="card24">${calendar}<p class="subtitle24">实心浅色为已记录，虚线为预测；点击日期记录经量、疼痛和感受。</p></div><button class="secondary full" id="periodDay24">记录今天的身体感受</button><h3>历史记录 · ${periods.length} 次</h3>${periods.slice().sort((a,b)=>b.start.localeCompare(a.start)).map(p=>`<button class="entry24" data-period-edit24="${p.id}"><b>${p.start} — ${p.end}</b><small>${Math.round((F24.date(p.end)-F24.date(p.start))/86400000)+1} 天 · ${escapeHtml(p.flow||'未记经量')}</small><p>${escapeHtml(p.note||'')}</p></button>`).join('')}<p class="api-note">预测按历史间隔估算，可能提前或推迟，不用于诊断、避孕或判断怀孕。身体记录不会自动交给聊天 API。</p>`);const step=n=>{const old=month24;month24=periodMonth24;monthShift24(n);periodMonth24=month24;month24=old;renderPeriod()};$('#monthPrev24').onclick=()=>step(-1);$('#monthNext24').onclick=()=>step(1);$('#periodOther24').onclick=()=>editPeriod();screen.querySelectorAll('[data-period-edit24]').forEach(b=>b.onclick=()=>editPeriod(b.dataset.periodEdit24));$('#periodSettings24').onclick=periodSettings24;$('#periodDay24').onclick=()=>periodDetail24(today);screen.querySelectorAll('[data-period24]').forEach(b=>b.onclick=()=>periodDetail24(b.dataset.period24));$('#periodStart24').onclick=()=>{try{if(!active){if(periods.some(p=>today>=p.start&&today<=p.end))throw Error('今天已在经期记录内，可编辑原记录');periodSave24({...period24,active:today})}else{if(periods.some(p=>active<=p.end&&today>=p.start))throw Error('与已有记录重叠，请先编辑原记录');const next=[...periods,{id:crypto.randomUUID(),start:active,end:today,flow:period24.days[today]?.flow||'未记录',note:''}];periodCommit24({...period24,active:null},next,periodCycle)}renderPeriod()}catch(e){toast(e.message)}}};
function periodSettings24(){const d=wxPanel(`<form id="periodConfig24"><h2>周期设置</h2><label>无足够历史记录时的参考周期<input name="cycle" type="number" min="15" max="90" required value="${periodCycle}"></label><label>预计经期长度<input name="length" type="number" min="1" max="15" required value="${period24.length}"></label><p>有历史记录时，参考最近六次有效间隔的平均值。</p><button class="primary full">保存</button></form>`);$('#periodConfig24').onsubmit=e=>{e.preventDefault();try{const cycle=Number(e.target.cycle.value),length=Number(e.target.length.value);if(!Number.isInteger(cycle)||cycle<15||cycle>90||!Number.isInteger(length)||length<1||length>15)throw Error('请填写有效天数');periodCommit24({...period24,length},periods,cycle);d.close();renderPeriod()}catch(err){toast(err.message)}}}
function periodDetail24(date){if(date>day24()){toast('未来日期仅作预测显示');return}const old=period24.days[date]||{},d=wxPanel(`<form id="periodDetail24"><h2>${date} · 身体日记</h2><label>经量<select name="flow">${['未记录','少量','适中','较多'].map(v=>`<option ${old.flow===v?'selected':''}>${v}</option>`).join('')}</select></label><label>疼痛感<select name="pain">${['无','轻微','中等','明显'].map(v=>`<option ${old.pain===v?'selected':''}>${v}</option>`).join('')}</select></label><fieldset><legend>今天的感受</legend>${['疲惫','腰酸','腹胀','头痛','睡眠不佳','精神不错'].map(v=>`<label class="check"><input name="symptom" type="checkbox" value="${v}" ${old.symptoms?.includes(v)?'checked':''}>${v}</label>`).join('')}</fieldset><label>备注<textarea name="note" rows="3" maxlength="2000">${escapeHtml(old.note||'')}</textarea></label><button class="primary full">保存感受</button><button class="secondary full" type="button" id="markStart24">将这天补记为经期开始</button></form>`);$('#markStart24').onclick=()=>{d.close();editPeriod();$('#periodForm').start.value=date;$('#periodForm').end.value=date};$('#periodDetail24').onsubmit=e=>{e.preventDefault();try{const f=e.target;periodSave24({...period24,days:{...period24.days,[date]:{flow:f.flow.value,pain:f.pain.value,symptoms:[...f.querySelectorAll('[name=symptom]:checked')].map(i=>i.value),note:f.note.value}}});d.close();renderPeriod()}catch(err){toast(err.message)}}}
render();

function periodCommit24(state,rows,cycle){const keys=['palais.period24','palais.periods','palais.cycle'],old=keys.map(k=>localStorage.getItem(k));try{localSave('period24',state);localSave('periods',rows);localSave('cycle',cycle)}catch(e){keys.forEach((k,i)=>{if(old[i]===null)localStorage.removeItem(k);else localStorage.setItem(k,old[i])});throw e}period24=state;periods=rows;periodCycle=cycle}
